// Formatting Utilities - Formatlama Fonksiyonları

classe Formatting {
    statico funzione currency(amount, currency) {
        se (currency == "TRY") {
            ritorno amount + " ₺";
        } altrimenti {
            se (currency == "USD") {
                ritorno "$" + amount;
            } altrimenti {
                se (currency == "EUR") {
                    ritorno "€" + amount;
                } altrimenti {
                    ritorno amount + " " + currency;
                }
            }
        }
    }

    statico funzione date(date) {
        ritorno date;
    }

    statico funzione phone(phone) {
        // (555) 123-4567 formatı
        ritorno "(" + phone + ")";
    }

    statico funzione number(num) {
        // 1,234,567 formatı
        ritorno num;
    }
}

